"""Gate 7 workspace Email Centre.

Provides a secure, same-origin mailbox UI over the proven Gate 7 mailbox APIs.
The UI deliberately uses the existing Core authentication and tenant isolation;
it never accepts a tenant id from the browser.
"""
from fastapi import Response
from fastapi.responses import HTMLResponse

from app_gate10 import app


EMAIL_CENTRE_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Zorvian Email Centre</title><link rel="stylesheet" href="/mailbox-centre.css"></head>
<body><main class="shell">
<header><div><div class="eyebrow">ZORVIAN · SECURE CLIENT CONTROL ROOM</div><h1>Email Centre</h1><p id="mailboxLine">Secure workspace communications</p></div><div class="status" id="statusPill">NOT SIGNED IN</div></header>
<section id="loginPanel" class="panel login"><h2>Secure sign in</h2><div class="grid2"><label>Email<input id="loginEmail" type="email" autocomplete="username"></label><label>Password<input id="loginPassword" type="password" autocomplete="current-password"></label></div><label>Authenticator code, if enabled<input id="loginOtp" inputmode="numeric" maxlength="6"></label><button id="loginBtn">SIGN IN SECURELY</button><p class="error" id="loginError"></p></section>
<section id="appPanel" class="hidden">
<nav><button data-view="inbox" class="active">INBOX</button><button data-view="sent">SENT</button><button data-view="compose">COMPOSE</button><button id="refreshBtn">REFRESH</button><button id="logoutBtn" class="quiet">LOG OUT</button></nav>
<div class="summary"><div><span>Mailbox</span><strong id="mailboxStatus">—</strong></div><div><span>Inbound</span><strong id="inboundCount">0</strong></div><div><span>Sent</span><strong id="sentCount">0</strong></div><div><span>Address</span><strong id="inboundAddress">—</strong></div></div>
<section id="messageView" class="panel"><div class="split"><div><h2 id="listTitle">Inbox</h2><div id="messageList" class="messageList"></div></div><article id="threadPane" class="threadPane"><div class="empty">Select a conversation</div></article></div></section>
<section id="composeView" class="panel hidden"><h2>Compose professional email</h2><div class="compose"><label>To<input id="to" type="email" placeholder="recipient@example.com"></label><label>Subject<input id="subject" maxlength="200"></label><label>Message<textarea id="body" rows="10" maxlength="20000"></textarea></label><input id="threadId" type="hidden"><div class="actions"><button id="sendBtn">SEND SECURELY</button><button id="cancelCompose" class="quiet">CANCEL</button></div><p id="sendResult"></p></div></section>
</section></main><script src="/mailbox-centre.js"></script></body></html>'''

EMAIL_CENTRE_CSS = r''':root{font-family:Arial,Helvetica,sans-serif;background:#050505;color:#f4efe5;--gold:#d0aa4e;--line:#4a3a12;--panel:#0b0b0b;--muted:#a89f90}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0,#181208 0,#050505 34%);min-height:100vh}.shell{width:min(1180px,94vw);margin:34px auto;border:1px solid var(--line);background:#080808;box-shadow:0 30px 70px #000}header{padding:28px 32px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;align-items:center}.eyebrow{letter-spacing:.19em;font-size:12px;font-weight:700}h1{font-family:Georgia,serif;font-size:38px;margin:8px 0 4px}h2{font-family:Georgia,serif;font-weight:500;margin-top:0}p{color:var(--muted)}.status{border:1px solid var(--line);padding:11px 15px;color:var(--gold);font-size:12px;font-weight:800;letter-spacing:.08em}.panel{margin:24px 32px;padding:24px;border:1px solid var(--line);background:var(--panel)}.login{max-width:760px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:block;color:#e5c76f;font-size:12px;font-weight:700;letter-spacing:.05em;margin:10px 0}input,textarea{width:100%;margin-top:7px;background:#050505;border:1px solid #514419;color:#fff;padding:13px;font:inherit;outline:none}input:focus,textarea:focus{border-color:var(--gold)}button{background:linear-gradient(180deg,#e2bf5b,#b88721);border:0;color:#070707;font-weight:900;letter-spacing:.05em;padding:12px 18px;cursor:pointer}button.quiet,nav button{background:#0b0b0b;color:#d9d1c1;border:1px solid var(--line)}nav button.active{background:var(--gold);color:#050505}nav{padding:20px 32px 0;display:flex;gap:8px;flex-wrap:wrap}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 32px}.summary div{border:1px solid var(--line);padding:15px}.summary span{display:block;color:#9d927e;font-size:10px;letter-spacing:.12em;text-transform:uppercase}.summary strong{display:block;margin-top:7px;color:#f4e3a7;word-break:break-word}.split{display:grid;grid-template-columns:minmax(290px,40%) 1fr;min-height:430px}.messageList{border-right:1px solid var(--line);padding-right:18px}.msg{padding:14px;border-bottom:1px solid #2d260f;cursor:pointer}.msg:hover,.msg.active{background:#121008}.msg .top{display:flex;justify-content:space-between;gap:8px}.msg strong{color:#f3dfa0}.msg small{color:#8f8677}.msg p{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin:7px 0 0}.threadPane{padding:0 0 0 24px}.bubble{border:1px solid #332a10;padding:16px;margin-bottom:12px}.bubble.outbound{border-left:3px solid var(--gold)}.bubble.inbound{border-left:3px solid #a8a8a8}.meta{font-size:11px;color:#998f7d;margin-bottom:8px}.empty{color:#807767;padding:80px 20px;text-align:center}.compose{max-width:800px}.actions{display:flex;gap:10px}.hidden{display:none!important}.error{color:#e38b8b}@media(max-width:800px){.grid2,.summary,.split{grid-template-columns:1fr}.messageList{border-right:0;border-bottom:1px solid var(--line);padding:0 0 18px}.threadPane{padding:22px 0 0}header{align-items:flex-start;flex-direction:column}}'''

EMAIL_CENTRE_JS = r'''(()=>{const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let token=sessionStorage.getItem('zorvian_mail_token')||'',messages=[],view='inbox';async function api(path,opt={}){const h={'Content-Type':'application/json',...(opt.headers||{})};if(token)h.Authorization='Bearer '+token;const r=await fetch(path,{...opt,headers:h});let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.detail||('Request failed '+r.status));return j}function signedIn(v){$('#loginPanel').classList.toggle('hidden',v);$('#appPanel').classList.toggle('hidden',!v);$('#statusPill').textContent=v?'GUARDIAN SESSION ACTIVE':'NOT SIGNED IN'}async function login(){try{$('#loginError').textContent='';const d={email:$('#loginEmail').value,password:$('#loginPassword').value};if($('#loginOtp').value)d.otp=$('#loginOtp').value;const r=await api('/auth/login',{method:'POST',body:JSON.stringify(d)});token=r.token;sessionStorage.setItem('zorvian_mail_token',token);signedIn(true);await refresh()}catch(e){$('#loginError').textContent=e.message}}function logout(){token='';sessionStorage.removeItem('zorvian_mail_token');signedIn(false)}function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}async function refresh(){try{const s=await api('/mailbox/status');$('#mailboxStatus').textContent=s.status||'—';$('#inboundAddress').textContent=s.inbound_address||'—';$('#inboundCount').textContent=s.messages?.inbound||0;$('#sentCount').textContent=s.messages?.outbound||0;$('#mailboxLine').textContent=(s.display_name||'Workspace')+' · '+(s.inbound_address||'secure email');messages=await api('/mailbox/messages?limit=100');renderList()}catch(e){if(/401|session|token/i.test(e.message))logout();else $('#mailboxLine').textContent=e.message}}function filtered(){return messages.filter(m=>view==='inbox'?m.direction==='inbound':m.direction==='outbound')}function renderList(){const list=filtered();$('#listTitle').textContent=view==='inbox'?'Inbox':'Sent';$('#messageList').innerHTML=list.length?list.map(m=>`<div class="msg" data-id="${esc(m.id)}"><div class="top"><strong>${esc(m.subject||'(no subject)')}</strong><small>${esc((m.created_at||'').replace('T',' ').slice(0,16))}</small></div><small>${esc(view==='inbox'?m.from_addr:m.to_addr)}</small><p>${esc(m.text_body||'')}</p></div>`).join(''):'<div class="empty">No messages yet</div>';$$('.msg').forEach(x=>x.onclick=()=>showThread(x.dataset.id))}function showThread(id){$$('.msg').forEach(x=>x.classList.toggle('active',x.dataset.id===id));const m=messages.find(x=>x.id===id);if(!m)return;const thread=messages.filter(x=>x.thread_id===m.thread_id).sort((a,b)=>(a.created_at||'').localeCompare(b.created_at||''));$('#threadPane').innerHTML=`<h2>${esc(m.subject||'(no subject)')}</h2>${thread.map(x=>`<div class="bubble ${esc(x.direction)}"><div class="meta">${esc(x.direction.toUpperCase())} · ${esc(x.from_addr)} → ${esc(x.to_addr)} · ${esc((x.created_at||'').replace('T',' ').slice(0,19))}</div><div>${esc(x.text_body||'').replace(/\n/g,'<br>')}</div></div>`).join('')}<button id="replyBtn">REPLY</button>`;$('#replyBtn').onclick=()=>{const other=m.direction==='inbound'?m.from_addr:m.to_addr;openCompose(other,(m.subject||'').startsWith('Re:')?m.subject:'Re: '+(m.subject||''),m.thread_id)}}function switchView(v){view=v;$$('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#messageView').classList.toggle('hidden',v==='compose');$('#composeView').classList.toggle('hidden',v!=='compose');if(v!=='compose')renderList()}function openCompose(to='',subject='',thread=''){$('#to').value=to;$('#subject').value=subject;$('#body').value='';$('#threadId').value=thread||'';$('#sendResult').textContent='';switchView('compose')}async function send(){try{$('#sendResult').textContent='Sending…';const d={to:$('#to').value,subject:$('#subject').value,body:$('#body').value};if($('#threadId').value)d.thread_id=$('#threadId').value;const r=await api('/mailbox/send',{method:'POST',body:JSON.stringify(d)});$('#sendResult').textContent='Sent securely. Professional HTML applied.';await refresh();view='sent';switchView('sent');setTimeout(()=>showThread(r.id),150)}catch(e){$('#sendResult').textContent=e.message}}$('#loginBtn').onclick=login;$('#logoutBtn').onclick=logout;$('#refreshBtn').onclick=refresh;$('#sendBtn').onclick=send;$('#cancelCompose').onclick=()=>switchView('inbox');$$('nav [data-view]').forEach(b=>b.onclick=()=>b.dataset.view==='compose'?openCompose():switchView(b.dataset.view));signedIn(!!token);if(token)refresh()})();'''


@app.get("/mailbox-center", response_class=HTMLResponse)
def mailbox_center():
    return EMAIL_CENTRE_HTML


@app.get("/mailbox-centre.css")
def mailbox_center_css():
    return Response(EMAIL_CENTRE_CSS, media_type="text/css")


@app.get("/mailbox-centre.js")
def mailbox_center_js():
    return Response(EMAIL_CENTRE_JS, media_type="application/javascript")


@app.middleware("http")
async def mailbox_center_security_headers(request, call_next):
    response = await call_next(request)
    if request.url.path in {"/mailbox-center", "/mailbox-centre.css", "/mailbox-centre.js"}:
        response.headers["Content-Security-Policy"] = "default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"
        response.headers["Cache-Control"] = "no-store"
    return response
